+  public long getCpus() throws IOException {
+    long quota = Long.parseLong(Files.readString(path.resolve("cpu.cfs_quota_us")).trim());
+    long period = Long.parseLong(Files.readString(path.resolve("cpu.cfs_period_us")).trim());
+    return quota / period;
+  }
+}

