-  @VisibleForTesting
-  static class StarlarkEvaluationException extends Exception {
-    public StarlarkEvaluationException(String message) {
-      super(message);
-    }
-
-    public StarlarkEvaluationException(String message, Throwable cause) {
-      super(message, cause);
-    }
-  }
-}

